program.script:
let last;
let learned = "";
for (let i = 1; i <= args.rounds; i++) {
  await phase("round " + i);
  const round = await task(args.goal + learned, {
    label: "r" + i,
    from: last,
    schema: { type: "object", required: ["done", "learned"], properties: { done: { type: "boolean" }, learned: { type: "string" } } },
  });
  if (!round) break;
  last = "r" + i;
  learned = "\nThe last round learned: " + round.learned;
  if (round.done) break;
}
return { branch: last };
